@extends('layouts.admin')
@section('title','Check Domain')
@section('content')
<style>
.cd{--ink:#14213d;--muted:#667085;--line:#e4e7ec;--soft:#f7f9fc;--brand:#17365d;--green:#16794a;--amber:#9a6700;--red:#b42318;font-size:14px}.cd *{box-sizing:border-box}.cd .hero,.cd .panel{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 3px 14px rgba(16,24,40,.04)}.cd .hero{padding:22px;background:linear-gradient(135deg,#f7fbff,#fff)}.cd h2,.cd h3,.cd h4{margin:0;color:var(--ink)}.cd h2{font-size:25px}.cd h3{font-size:17px}.cd p.sub{margin:5px 0 15px;color:var(--muted);font-size:13px}.cd .grid{display:grid;grid-template-columns:2fr 1fr;gap:14px;margin-top:16px}.cd .panel{padding:18px}.cd .form{display:grid;grid-template-columns:2fr 1fr auto auto;gap:10px;align-items:end}.cd label{display:block;font-weight:650;color:#344054;margin-bottom:5px;font-size:13px}.cd input,.cd textarea{width:100%;border:1px solid #cfd6df;border-radius:9px;padding:10px;background:#fff;color:#172b4d;font:inherit}.cd textarea{min-height:120px;resize:vertical;font-family:ui-monospace,monospace;font-size:12px}.cd button{border:1px solid #c7d0da;border-radius:9px;padding:10px 13px;background:#fff;color:#17365d;font-weight:650;cursor:pointer}.cd button.primary{background:#17365d;border-color:#17365d;color:#fff}.cd .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.cd .quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cd .quick div{padding:9px;border:1px solid var(--line);border-radius:9px;background:var(--soft)}.cd .quick strong{display:block;font-size:13px;color:var(--ink)}.cd .quick span{font-size:11px;color:var(--muted)}.cd .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}.cd .card{border:1px solid var(--line);border-radius:11px;padding:13px}.cd .card h4{font-size:14px;margin-bottom:9px}.cd .kv{display:grid;grid-template-columns:105px 1fr;gap:5px 9px;font-size:12px}.cd .kv b{color:#667085}.cd .kv span{word-break:break-word}.cd .records-wrap,.cd .bulk-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px;margin-top:12px}.cd table{width:100%;border-collapse:collapse;font-size:12px}.cd th,.cd td{padding:7px 8px;border:1px solid var(--line);vertical-align:top;text-align:left}.cd th{background:#f3f6f8;color:#344054}.cd .mono{font-family:ui-monospace,monospace;font-size:11px}.cd .bulk-table{width:max-content;min-width:100%;font-size:11.5px}.cd .bulk-table th,.cd .bulk-table td{white-space:nowrap}.cd .bulk-table .group th{background:#17365d;color:#fff;text-align:center}.cd .bulk-table .web{background:#3c6e71}.cd .bulk-table .ssl{background:#6c5b7b}.cd .bulk-table .ip{background:#7b5e57}.cd .bulk-table .dns{background:#4f6d4f}.cd .bulk-table .mail{background:#8a6d3b}.cd .bulk-table .provider{background:#52616b}.cd .bulk-table .error{background:#7f1d1d}.cd .wrap{white-space:normal!important;min-width:180px;max-width:320px;word-break:break-word}.cd .pill{display:inline-block;padding:5px 9px;border-radius:999px;background:#ecfdf3;color:var(--green);font-weight:700;font-size:12px}.cd .bad{background:#fef3f2;color:var(--red)}.cd .loading{display:none;margin-top:10px;color:var(--muted);font-size:12px}@media(max-width:1000px){.cd .grid{grid-template-columns:1fr}.cd .cards{grid-template-columns:1fr 1fr}}@media(max-width:650px){.cd .form,.cd .cards{grid-template-columns:1fr}.cd .quick{grid-template-columns:1fr}}
</style>
<div class="cd">
<div class="hero"><h2>Check Domain</h2><p class="sub">Kiểm tra tập trung Domain, DNS, SSL/TLS, Website, Email, IP/Hosting và Service Discovery.</p></div>
<div class="grid">
<section class="panel"><h3>Single Domain Audit</h3><p class="sub">Kiểm tra một domain bằng toàn bộ module backend hiện có.</p><form id="audit-form">@csrf<div class="form"><div><label>Domain *</label><input id="domain" required placeholder="example.com hoặc example.vn"></div><div><label>WAN / Origin IP</label><input id="wan_ip" placeholder="1.2.3.4"></div><button class="primary" type="submit">▶ Run Audit</button><button type="button" id="clear-single">Clear</button></div><details style="margin-top:12px"><summary style="cursor:pointer;font-weight:650;color:#344054">Advanced Options — Email & Service Discovery</summary><div class="grid" style="margin-top:10px"><div><label>DKIM Selectors</label><input id="dkim_selectors" placeholder="selector1, selector2"></div><div><label>Service Hosts</label><input id="service_hosts" placeholder="vpn, mail, portal"></div></div></details></form><div id="single-loading" class="loading">Đang thực hiện audit...</div></section>
<aside class="panel"><h3>Audit Coverage</h3><p class="sub">Capability đang được kiểm tra trực tiếp.</p><div class="quick"><div><strong>🌐 Domain</strong><span>Expiry · Registrar · Status</span></div><div><strong>🧭 DNS</strong><span>RR types · DNSSEC · Provider</span></div><div><strong>🔐 SSL / TLS</strong><span>CA · SAN · TLS · Cipher</span></div><div><strong>🖥 Website</strong><span>HTTP/HTTPS · Redirect · Headers</span></div><div><strong>✉ Email</strong><span>MX · SPF · DMARC · DKIM</span></div><div><strong>☁ Infrastructure</strong><span>IP · ASN · Network · CDN · WAF</span></div><div><strong>🔎 Services</strong><span>Default/custom hosts</span></div><div><strong>📊 Operations</strong><span>Bulk · Excel</span></div></div></aside>
<section class="panel" style="grid-column:1/-1"><h3>Bulk Audit</h3><p class="sub">Tối đa 100 domain/lần. Mỗi dòng: domain hoặc domain,wan_ip.</p><textarea id="bulk-items" placeholder="zenbooks.vn\nexample.vn,1.2.3.4\ncompany.com"></textarea><div class="actions"><button id="bulk-run" class="primary" type="button">▶ Run Bulk Audit</button><button id="bulk-clear" type="button">Clear List</button></div></section></div>
<div id="result" style="margin-top:16px"></div><div id="bulk-result" style="margin-top:16px"></div></div>
<script>
const csrf=document.querySelector('[name=_token]').value;const arr=v=>Array.isArray(v)?v:[];const val=(v,f='—')=>(v===null||v===undefined||v==='')?f:v;const esc=v=>String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));const days=v=>{if(v===null||v===undefined||v==='')return'N/A';const n=Number(v);return Number.isFinite(n)?Math.floor(n).toLocaleString('en-US')+' days':String(v)};const bool=v=>v===true?'YES':v===false?'NO':'—';
function card(t,items){return`<div class="card"><h4>${t}</h4><div class="kv">${items.map(([k,v])=>`<b>${esc(k)}</b><span>${esc(v)}</span>`).join('')}</div></div>`}function records(r){let rows=[];Object.entries(r||{}).forEach(([type,list])=>arr(list).forEach(x=>{const y={...x};delete y.type;rows.push([type,Object.entries(y).map(([k,v])=>k+'='+v).join(' · ')])}));return rows.length?`<div class="records-wrap"><table><thead><tr><th>Type</th><th>Record</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x[0])}</b></td><td class="mono">${esc(x[1])}</td></tr>`).join('')}</tbody></table></div>`:'<p>No DNS records returned.</p>'}
async function requestAudit(item){const r=await fetch('{{ route('admin.it_tools.audit') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(item)});const text=await r.text();let d={};try{d=text?JSON.parse(text):{}}catch(_){throw new Error('Server returned non-JSON response (HTTP '+r.status+').')}if(!r.ok)throw new Error(d.message||('Audit failed (HTTP '+r.status+')'));return d}
async function exportRows(rows){if(!rows.length){alert('Không có dòng kết quả để Export Excel.');return}const r=await fetch('{{ route('admin.it_tools.export') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({rows})});if(!r.ok){let m='Export Excel failed (HTTP '+r.status+')';try{const d=await r.json();m=d.message||m}catch(_){}throw new Error(m)}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='it-tools-check-domain-'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')+'.xlsx';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function renderSingle(a){const d=a.domain_audit||{},dns=a.dns_audit||{},s=a.ssl_audit||{},w=a.website_audit||{},h=w.http||{},hs=w.https||{},e=a.email_audit||{},i=a.ip_audit||{},p=a.provider_detection||{},sv=a.service_discovery||{},services=arr(sv.services),overall=(d.status==='ok'||d.status==='available')&&s.status==='ok'&&hs.online,dkim=Object.entries(e.dkim||{}).map(([k,v])=>k+': '+(v.present?'PASS':'MISSING')).join('; ')||'Not checked';window.singleRows=[{status:'ok',domain:a.domain,wan_ip:a.wan_ip_supplied||null,audit:a}];document.getElementById('result').innerHTML=`<section class="panel"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h3>Audit Result — ${esc(a.domain)}</h3><p class="sub">Checked: ${esc(a.checked_at||'—')}</p></div><button id="single-export">⇩ Export Excel</button></div><span class="pill ${overall?'':'bad'}">${overall?'● AUDIT OK':'● REVIEW REQUIRED'}</span><div class="cards">${card('🌐 Domain',[['Status',val(d.status)],['Registrar',val(d.registrar)],['Created',val(d.created_at)],['Expiry',val(d.expires_at,'N/A')],['Days Left',days(d.days_remaining)],['Source',val(d.source)],['Nameservers',arr(d.nameservers).join(', ')||'—']])}${card('🔐 SSL / TLS',[['Status',val(s.status)],['Vendor',val(s.vendor,'N/A')],['Issuer',val(s.issuer)],['Valid To',val(s.valid_to,'N/A')],['Days Left',days(s.days_remaining)],['Hostname Match',bool(s.verify)],['TLS Version',val(s.tls_version)],['Cipher',val(s.cipher)]])}${card('🖥 Website',[['HTTP',val(h.status)],['HTTP Online',bool(h.online)],['HTTP Response',val(h.response_time_ms)+' ms'],['HTTPS',val(hs.status)],['HTTPS Online',bool(hs.online)],['HTTPS Response',val(hs.response_time_ms)+' ms'],['HTTPS Final URL',val(hs.final_url)],['HSTS',bool(hs.hsts)]])}${card('☁ IP / Hosting',[['Primary IP',val(i.ip,'N/A')],['Resolved IPv4',arr(a.resolved_ipv4).join(', ')||'—'],['ASN',val(i.asn)],['Network',val(i.network)],['Organization',val(i.organization)],['IP Provider',val(i.provider)],['Hosting Provider',val(p.hosting_provider)],['CDN',val(p.cdn)],['WAF',val(p.waf)]])}${card('✉ Email Security',[['Mail Provider',val(e.provider,'N/A')],['MX Count',arr(e.mx).length],['SPF',e.spf_present?'PASS':'MISSING'],['DMARC',e.dmarc_present?'PASS':'MISSING'],['DKIM',dkim],['MTA-STS',e.mta_sts_present?'PASS':'MISSING'],['TLS-RPT',e.tls_rpt_present?'PASS':'MISSING']])}${card('🧭 DNS Summary',[['Provider',val(dns.dns_provider,'N/A')],['Nameservers',arr(dns.dns_nameservers).join(', ')||'N/A'],['DNSSEC',dns.dnssec?'DETECTED':'NOT DETECTED'],['Found Types',arr(dns.record_types_found).join(', ')||'—'],['Query Mode',val(dns.dns_query_mode)]])}</div><details style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">DNS Records — All Returned RRsets</summary>${records(dns.records||{})}</details><details style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">Service Discovery — ${services.length} Hosts</summary><div class="records-wrap"><table><thead><tr><th>Hostname</th><th>IPs</th><th>HTTP</th><th>HTTPS</th><th>Status</th></tr></thead><tbody>${services.map(x=>`<tr><td class="mono">${esc(x.hostname)}</td><td class="mono">${esc(arr(x.ips).join(', ')||'—')}</td><td>${esc(val(x.http?.status))}</td><td>${esc(val(x.https?.status))}</td><td><b>${esc(String(x.status||'').toUpperCase())}</b></td></tr>`).join('')}</tbody></table></div></details></section>`;document.getElementById('single-export').onclick=async()=>{const b=document.getElementById('single-export');b.disabled=true;try{await exportRows(window.singleRows)}catch(e){alert(e.message)}finally{b.disabled=false}}}
document.getElementById('audit-form').onsubmit=async e=>{e.preventDefault();const l=document.getElementById('single-loading');l.style.display='block';try{renderSingle(await requestAudit({domain:document.getElementById('domain').value.trim(),wan_ip:document.getElementById('wan_ip').value.trim()||null,dkim_selectors:document.getElementById('dkim_selectors').value.trim(),service_hosts:document.getElementById('service_hosts').value.trim()}))}catch(x){document.getElementById('result').innerHTML=`<section class="panel"><span class="pill bad">● ERROR</span><p>${esc(x.message)}</p></section>`}finally{l.style.display='none'}};document.getElementById('clear-single').onclick=()=>{['domain','wan_ip','dkim_selectors','service_hosts'].forEach(id=>document.getElementById(id).value='');document.getElementById('result').innerHTML='';window.singleRows=[]};
function parseBulk(t){return t.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>{const p=x.split(',').map(y=>y.trim());return{domain:p[0],wan_ip:p[1]||null}})}function serviceSummary(s){const r=arr(s?.services);return{checked:s?.checked_hosts??r.length,online:r.filter(x=>x.status==='online').length,notFound:r.filter(x=>x.status==='not_found').length,summary:r.map(x=>(x.hostname||x.label||'unknown')+'='+String(x.status||'unknown').toUpperCase()).join('; ')||'—'}}function bv(item){const a=item.audit||{},d=a.domain_audit||{},s=a.ssl_audit||{},w=a.website_audit||{},h=w.http||{},hs=w.https||{},i=a.ip_audit||{},e=a.email_audit||{},dns=a.dns_audit||{},p=a.provider_detection||{},sv=serviceSummary(a.service_discovery);return{checked:a.checked_at,domain:item.domain,wan:item.wan_ip||a.wan_ip_supplied||'—',status:item.status==='ok'?'OK':'ERROR',de:d.expires_at||'N/A',dd:days(d.days_remaining),ds:d.source||'—',http:h.status??'—',ho:bool(h.online),hu:h.final_url||'—',hr:h.response_time_ms??'—',hs:hs.status??'—',hso:bool(hs.online),hsu:hs.final_url||'—',sv:s.vendor||'N/A',se:s.valid_to||'N/A',sd:days(s.days_remaining),hm:bool(s.verify),ip:i.ip||'N/A',net:i.network||'—',asn:i.asn||'—',ipp:i.provider||'—',dp:dns.dns_provider||p.dns_provider||'N/A',ns:arr(dns.dns_nameservers).join(', ')||'N/A',sec:dns.dnssec?'DETECTED':'NOT DETECTED',types:arr(dns.record_types_found).join(', ')||'—',mx:arr(e.mx).length,mail:e.provider||'N/A',spf:e.spf_present?'PASS':'MISSING',dm:e.dmarc_present?'PASS':'MISSING',dk:Object.entries(e.dkim||{}).map(([k,v])=>k+': '+(v.present?'PASS':'MISSING')).join('; ')||'Not checked',mta:e.mta_sts_present?'PASS':'MISSING',rpt:e.tls_rpt_present?'PASS':'MISSING',cdn:p.cdn||'—',waf:p.waf||'—',host:p.hosting_provider||'—',sc:sv.checked,so:sv.online,sn:sv.notFound,ss:sv.summary,error:item.error||''}}function bulkRow(item){const v=bv(item),td=(x,c='')=>`<td class="${c}">${esc(x)}</td>`;return`<tr>${td(v.checked)}${td(v.domain)}${td(v.wan)}${td(v.status,v.status==='OK'?'':'bad')}${td(v.de)}${td(v.dd)}${td(v.ds)}${td(v.http)}${td(v.ho)}${td(v.hu,'wrap')}${td(v.hr)}${td(v.hs)}${td(v.hso)}${td(v.hsu,'wrap')}${td(v.sv)}${td(v.se)}${td(v.sd)}${td(v.hm)}${td(v.ip)}${td(v.net)}${td(v.asn)}${td(v.ipp)}${td(v.dp)}${td(v.ns,'wrap')}${td(v.sec)}${td(v.types)}${td(v.mx)}${td(v.mail)}${td(v.spf)}${td(v.dm)}${td(v.dk,'wrap')}${td(v.mta)}${td(v.rpt)}${td(v.cdn)}${td(v.waf)}${td(v.host)}${td(v.sc)}${td(v.so)}${td(v.sn)}${td(v.ss,'wrap')}${td(v.error,'wrap')}</tr>`}function renderBulk(results,total){window.bulkRows=results;const groups=[['Audit',4,''],['Domain',3,''],['Website / HTTP',4,'web'],['Website / HTTPS',3,'web'],['SSL / TLS',4,'ssl'],['IP / Hosting',4,'ip'],['DNS Summary',5,'dns'],['Email Security',6,'mail'],['Provider / Service Discovery',7,'provider'],['Error',1,'error']],hs=['Checked At','Domain','WAN IP','Status','Domain Expiry','Domain Days','Domain Source','HTTP Status','HTTP Online','HTTP Final URL','HTTP ms','HTTPS Status','HTTPS Online','HTTPS Final URL','SSL Vendor','SSL Expiry','SSL Days','Hostname','Primary IP','Network','ASN','IP Provider','DNS Provider','Nameservers','DNSSEC','Record Types','MX','Mail Provider','SPF','DMARC','DKIM','MTA-STS','TLS-RPT','CDN','WAF','Hosting Provider','Services Checked','Services Online','Services Not Found','Service Summary','Error'];document.getElementById('bulk-result').innerHTML=`<section class="panel"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h3>Bulk Result</h3><p class="sub">${results.length} / ${total} completed · DNS summary only</p></div><button id="bulk-export">⇩ Export Excel</button></div><div class="bulk-wrap"><table class="bulk-table"><thead><tr class="group">${groups.map(g=>`<th colspan="${g[1]}" class="${g[2]}">${g[0]}</th>`).join('')}</tr><tr>${hs.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${results.map(bulkRow).join('')}</tbody></table></div></section>`;document.getElementById('bulk-export').onclick=async()=>{const b=document.getElementById('bulk-export');b.disabled=true;try{await exportRows(window.bulkRows)}catch(e){alert(e.message)}finally{b.disabled=false}}}
document.getElementById('bulk-run').onclick=async()=>{const items=parseBulk(document.getElementById('bulk-items').value);if(!items.length){alert('Please enter at least one domain.');return}const b=document.getElementById('bulk-run');b.disabled=true;b.textContent='Running...';try{const r=await fetch('{{ route('admin.it_tools.bulk_audit') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({items})}),d=await r.json();if(!r.ok)throw new Error(d.message||('Bulk audit failed (HTTP '+r.status+')'));renderBulk(d.results||[],d.requested||items.length)}catch(e){document.getElementById('bulk-result').innerHTML=`<section class="panel"><span class="pill bad">● ERROR</span><p>${esc(e.message)}</p></section>`}finally{b.disabled=false;b.textContent='▶ Run Bulk Audit'}};document.getElementById('bulk-clear').onclick=()=>{document.getElementById('bulk-items').value='';document.getElementById('bulk-result').innerHTML='';window.bulkRows=[]};
</script>
@endsection
